1	package security
2	
3	import (
4		"fmt"
5		"path/filepath"
6		"regexp"
7		"strings"
8	
9		"charm.land/lipgloss/v2"
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	// Caps on the Message section of a finding detail (DEVDESK-750): a scanner can
16	// hand back a whole stderr, and the detail shows the start of it.
17	const (
18		maxMessageWidth = 110
19		maxMessageLines = 8
20	)
21	
22	// scanMount is where a scanned directory is mounted inside a scanner container
23	// (scan.containerScanPath, unexported there).
24	const scanMount = "/scan"
25	
26	// pathToken finds an absolute path in a text: it starts at the beginning of the
27	// text or after a character that cannot be part of a path name, and stops at
28	// white space or punctuation that ends a path in a message.
29	var pathToken = REDACTED
30	
31	// shortPaths rewrites absolute paths inside text for display: "<target>/" and
32	// the container mount "/scan/" are removed, a bare target becomes ".", and any
33	// other path under HOME is folded to "~/". target is used only when it is an
34	// absolute path (an image reference is ignored). Display only: the finding
35	// keeps its text.
36	func shortPaths(text, target string) string {
37		if text == "" {
38			return ""
39		}
40		root := ""
41		if filepath.IsAbs(target) {
42			if root = filepath.ToSlash(filepath.Clean(target)); root == "/" {
43				root = ""
44			}
45		}
46		return pathToken.ReplaceAllStringFunc(text, func(match string) string {
47			at := strings.IndexByte(match, '/')
48			path, tail := match[at:], ""
49			// A sentence can end on a path: "cannot read /repo."
50			if trimmed := strings.TrimRight(path, "."); trimmed != "" {
51				path, tail = trimmed, path[len(trimmed):]
52			}
53			return match[:at] + shortPath(path, root) + tail
54		})
55	}
56	
57	// shortPath shortens one absolute path: relative to the target, relative to the
58	// container mount, or folded under HOME.
59	func shortPath(path, root string) string {
60		for _, base := range []string{root, scanMount} {
61			switch {
62			case base == "":
63			case path == base:
64				return "."
65			case strings.HasPrefix(path, base+"/"):
66				if rest := strings.TrimLeft(path[len(base):], "/"); rest != "" {
67					return rest
68				}
69				return "."
70			}
71		}
72		return theme.FoldHome(path)
73	}
74	
75	// oneLine is the first line of text, cut to width cells with theme.Ellipsis.
76	// It measures with x/ansi, as the viewport does, not with runewidth, after the
77	// tabs and carriage returns are gone: x/ansi counts a tab as no cell while the
78	// renderer lays it out as four spaces.
79	func oneLine(text string, width int) string {
80		if width <= 0 {
81			return ""
82		}
83		first, _, _ := strings.Cut(text, "\n")
84		first = withoutControlSpace(first)
85		if ansi.StringWidth(first) <= width {
86			return first
87		}
88		return ansi.Truncate(first, width, theme.Ellipsis)
89	}
90	
91	// cappedLines wraps text at min(width, maxMessageWidth), hard-breaking a token
92	// longer than that, and keeps the first maxLines lines. hidden counts the wrapped
93	// lines left out. A blank text gives nil, 0.
94	func cappedLines(text string, width, maxLines int) (lines []string, hidden int) {
95		if strings.TrimSpace(text) == "" {
96			return nil, 0
97		}
98		text = strings.TrimRight(text, " \t\r\n")
99		lines = strings.Split(ansi.Wrap(text, max(min(width, maxMessageWidth), 1), ""), "\n")
100		if len(lines) > maxLines {
101			return lines[:maxLines], len(lines) - maxLines
102		}
103		return lines, 0
104	}
105	
106	// moreLines is the marker after a capped text, "" when nothing was left out.
107	func moreLines(n int) string {
108		switch {
109		case n <= 0:
110			return ""
111		case n == 1:
112			return "… 1 more line"
113		}
114		return fmt.Sprintf("… %d more lines", n)
115	}
116	
117	// scrollPosition is "Lines a-b of N" when the content is taller than the
118	// viewport, "" otherwise.
119	func scrollPosition(offset, visible, total int) string {
120		if visible <= 0 || total <= visible {
121			return ""
122		}
123		offset = max(offset, 0)
124		return fmt.Sprintf("Lines %d-%d of %d", offset+1, min(offset+visible, total), total)
125	}
126	
127	// withoutControlSpace drops carriage returns and turns a tab into four spaces,
128	// which is how the renderer lays it out.
129	func withoutControlSpace(text string) string {
130		return strings.ReplaceAll(strings.ReplaceAll(text, "\r", ""), "\t", "    ")
131	}
132	
133	// normalizeText makes a scanner's text safe to lay out: a tab or a carriage
134	// return has no width the viewport and the terminal agree on, trailing spaces
135	// are noise, and a run of blank lines is one blank line. dropBlank removes the
136	// blank lines altogether (a stderr, where they separate nothing).
137	func normalizeText(text string, dropBlank bool) string {
138		text = withoutControlSpace(text)
139		var out []string
140		for _, line := range strings.Split(text, "\n") {
141			line = strings.TrimRight(line, " ")
142			blank := line == ""
143			switch {
144			case blank && (dropBlank || len(out) == 0 || out[len(out)-1] == ""):
145			default:
146				out = append(out, line)
147			}
148		}
149		for len(out) > 0 && out[len(out)-1] == "" {
150			out = out[:len(out)-1]
151		}
152		return strings.Join(out, "\n")
153	}
154	
155	// dropBlankLines is normalizeText without any blank line.
156	func dropBlankLines(text string) string { return normalizeText(text, true) }
157	
158	// detailsText lays text out for the finding detail: every line it returns is
159	// styled on the theme background and spans at most width cells, measured with
160	// x/ansi as the viewport does.
161	type detailsText struct {
162		width int            // cells a line may span
163		text  lipgloss.Style // ordinary text
164		dim   lipgloss.Style // secondary text
165	}
166	
167	func newDetailsText(width int) detailsText {
168		return detailsText{
169			width: width,
170			text:  lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText),
171			dim:   theme.DimStyle,
172		}
173	}
174	
175	// block wraps text at the full width, one styled line per entry.
176	func (t detailsText) block(text string, style lipgloss.Style) []string {
177		return t.indented("", text, style)
178	}
179	
180	// indented wraps text under a prefix of spaces.
181	func (t detailsText) indented(prefix, text string, style lipgloss.Style) []string {
182		text = normalizeText(text, false)
183		if text == "" {
184			return nil
185		}
186		room := max(t.width-ansi.StringWidth(prefix), 1)
187		var lines []string
188		for _, line := range strings.Split(ansi.Wrap(text, room, ""), "\n") {
189			line = strings.TrimRight(line, " ")
190			if line == "" {
191				lines = append(lines, "")
192				continue
193			}
194			lines = append(lines, theme.Bg(prefix)+style.Render(line))
195		}
196		return lines
197	}
198	
199	// field is a label and its value, the value wrapped under itself. When the label
200	// leaves too little room for the value, the value goes on the lines below.
201	func (t detailsText) field(label, value string, style lipgloss.Style) []string {
202		value = normalizeText(value, false)
203		if value == "" {
204			return nil
205		}
206		labelWidth := ansi.StringWidth(label)
207		if t.width-labelWidth < minFieldValueWidth {
208			return append([]string{theme.SubTitleStyle.Render(strings.TrimRight(label, " "))}, t.block(value, style)...)
209		}
210		lines := strings.Split(ansi.Wrap(value, t.width-labelWidth, ""), "\n")
211		out := make([]string, 0, len(lines))
212		for i, line := range lines {
213			line = style.Render(strings.TrimRight(line, " "))
214			if i == 0 {
215				out = append(out, theme.SubTitleStyle.Render(label)+line)
216			} else {
217				out = append(out, theme.Bg(strings.Repeat(" ", labelWidth))+line)
218			}
219		}
220		return out
221	}
222	
223	// minFieldValueWidth is the least room a value needs beside its label.
224	const minFieldValueWidth = 12
225

1	package security
2	
3	import (
4		"github.com/anthnel/devdesk/internal/scan"
5	)
6	
7	// fixStatus is the fix line of a finding detail, in words: a colour or a key
8	// name alone would not say it (Rule 134), so the status never names a key.
9	type fixStatus struct {
10		Label   string // words, never a colour alone; "" = no status line
11		Detail  string // reason, MissingFor text, catalog rule title, or ""
12		Warning string // remediation.Rule.Warning, or ""
13	}
14	
15	// fixStatusOf says whether f can be fixed and why not. For a misconfiguration
16	// it reads misconfigFixAvailability, the computation behind the shortcut column,
17	// so the detail and the header agree. Secrets, licenses and CI scores have no
18	// fix status: the zero value, no line.
19	func fixStatusOf(f scan.Finding, onDisk bool) fixStatus {
20		switch scan.Categorize(f) {
21		case scan.CategoryVulnerability:
22			if f.FixedIn != "" {
23				return fixStatus{Label: "Fix available", Detail: "Fixed in " + f.FixedIn}
24			}
25			return fixStatus{Label: "No fix available", Detail: "No fixed version is published"}
26		case scan.CategoryMisconfiguration:
27			return misconfigFixStatus(f, onDisk)
28		}
29		return fixStatus{}
30	}
31	
32	func misconfigFixStatus(f scan.Finding, onDisk bool) fixStatus {
33		rule, a := misconfigFixAvailability(f, onDisk)
34		inCatalog := rule.AVDID != ""
35		switch {
36		case a.Enabled():
37			return fixStatus{Label: "Built-in fix available", Detail: rule.Title, Warning: rule.Warning}
38		case !onDisk && inCatalog:
39			return fixStatus{Label: "No built-in fix here", Detail: a.Reason}
40		case !inCatalog:
41			// On an image the availability reason is the image one; the finding's own
42			// reason is what explains the missing fix.
43			return fixStatus{Label: "No built-in fix", Detail: noFixReason(f)}
44		}
45		return fixStatus{Label: "No built-in fix for this instance", Detail: a.Reason}
46	}
47	
48	// fixAction says how to show f.FixCommand: ("Run", cmd) for a real command,
49	// ("", instruction) for a sentence such as "Update pkg to 1.2", ("", "") when
50	// there is none.
51	func fixAction(f scan.Finding) (label, text string) {
52		switch {
53		case f.FixCommand == "":
54			return "", ""
55		case scan.IsFixInstruction(f):
56			return "", f.FixCommand
57		}
58		return "Run", f.FixCommand
59	}
