43	// handleDetailsOpenReference opens the first reference URL in the default browser.
44	func (m Model) handleDetailsOpenReference() (tea.Model, tea.Cmd) {
45		if m.selectedFinding == nil {
46			return m, nil
47		}
48		f := *m.selectedFinding
49		if len(f.References) == 0 {
50			return m, m.footer.Warn("No references available")
51		}
52		url := f.References[0]
53		return m, func() tea.Msg {
54			if err := browser.Open(url); err != nil {
55				log.Printf("ERROR [security] open URL %s: %v", url, err)
56			}
57			return nil
58		}
59	}
