61	// sizeDetails gives the details viewport the room the router leaves it: the
62	// view's width less the two border cells the viewport frame takes, so a line
63	// never reaches under the right border. The padding takes one more cell on each
64	// side, which is the text width (detailsTextWidth).
65	func (m *Model) sizeDetails() {
66		m.detailsViewport.SetWidth(max(m.width-2, 1))
67		m.detailsViewport.SetHeight(m.height)
68	}
